    char network_adapter[64] = {0};

    // Parse the configuration line using sscanf with format specifiers
    // The format expects: cpu_model=%127[^,],memory_mb=%d,disk_path=%255[^,],network_adapter=%63[^,]
    int matched = sscanf(config_line, 
