int parse_vm_config(const char* config_line, struct vm_hardware_config* hw_config) {
    // Validate input pointers
    if (config_line == NULL || hw_config == NULL || config_line[0] == '\0') {
        return -1;
    }

    // Clear the structure to avoid uninitialized fields
    memset(hw_config, 0, sizeof(*hw_config));

    // Work on a mutable copy of the input line
    char* line_copy = strdup(config_line);
    if (line_copy == NULL) {
        return -1; // memory allocation failure
    }

    // Flags to track which fields have been set
    int found_cpu = 0, found_mem = 0, found_disk = 0, found_net = 0;

    // Tokenize by comma
    char* token = strtok(line_copy, ",");
    while (token != NULL) {
        // Find the '=' separator
        char* eq = strchr(token, '=');
        if (eq == NULL) {
            free(line_copy);
            return -1; // malformed token
        }

        // Split into key and value by replacing '=' with null
        *eq = '\0';
        const char* key = token;
        const char* value = eq + 1;

        // Parse the token
        if (parse_token(key, value, hw_config) != 0) {
            free(line_copy);
            return -1;
        }

        // Mark field as found
        if (strcmp(key, "cpu_model") == 0) found_cpu = 1;
        else if (strcmp(key, "memory_mb") == 0) found_mem = 1;
        else if (strcmp(key, "disk_path") == 0) found_disk = 1;
        else if (strcmp(key, "network_adapter") == 0) found_net = 1;

        token = strtok(NULL, ",");
    }

    free(line_copy);

    // All four required fields must be present
    if (!found_cpu || !found_mem || !found_disk || !found_net) {
        return -1;
    }

